# Singleton Pattern

A design pattern that restricts a class to a single instance and provides a global access point to it.

**When to use:** database connections, configuration managers, logging services — anything where multiple instances would cause conflicts or waste resources.

## Practical Example: Database Connection Manager

```javascript
class Database {
  constructor() {
    if (Database.instance) {
      return Database.instance;
    }

    this.connection = null;
    this.host = 'localhost';
    this.port = 5432;
    Database.instance = this;
  }

  connect() {
    if (this.connection) {
      console.log('Already connected, reusing existing connection.');
      return this.connection;
    }
    this.connection = { id: Math.random(), host: this.host, port: this.port };
    console.log(`New connection established: ${this.connection.id}`);
    return this.connection;
  }

  disconnect() {
    this.connection = null;
    console.log('Disconnected.');
  }

  static getInstance() {
    if (!Database.instance) {
      Database.instance = new Database();
    }
    return Database.instance;
  }
}

// Usage
const db1 = Database.getInstance();
const db2 = Database.getInstance();

console.log(db1 === db2); // true — same instance

db1.connect(); // New connection established: 0.7291...
db2.connect(); // Already connected, reusing existing connection.
```

## Simpler Module-Based Singleton (more idiomatic JS)

Since ES modules are cached after first evaluation, you get singleton behavior for free:

```javascript
// dbConnection.js
class Database {
  constructor() {
    this.connection = null;
  }

  connect(config) {
    if (!this.connection) {
      this.connection = { id: Date.now(), ...config };
    }
    return this.connection;
  }
}

const instance = new Database();
Object.freeze(instance);

export default instance;
```

```javascript
// anywhere in your app
import db from './dbConnection.js';
db.connect({ host: 'localhost' }); // always the same instance
```

## Tradeoffs

| Pro | Con |
|-----|-----|
| Controlled access to shared resource | Hidden dependencies (global state) |
| Lazy initialization | Harder to test (tight coupling) |
| Single point of configuration | Can mask design problems |

**My take:** In modern JS, the module-based approach is almost always preferable to the classical `getInstance()` pattern. It's cleaner, leverages the language's native module caching, and doesn't require the ceremony of static methods. Use the class-based version only if you need lazy initialization with deferred construction logic.

```go
package email

import (
	"net"
	"regexp"
	"strings"
)

// ValidateEmail checks if an email address is valid.
// It checks structure, length constraints, and character rules per RFC 5321/5322 (simplified).
// It does NOT verify the mailbox actually exists.
func ValidateEmail(email string) (bool, string) {
	// Overall length: RFC 5321 limits to 254 chars for deliverability
	if len(email) == 0 {
		return false, "empty string"
	}
	if len(email) > 254 {
		return false, "exceeds 254 character limit"
	}

	// Must have exactly one @
	atIndex := strings.LastIndex(email, "@")
	if atIndex == -1 {
		return false, "missing @ symbol"
	}
	if strings.Count(email, "@") > 1 {
		// Actually multiple @ are allowed if local part is quoted,
		// but for practical validation we use LastIndex to split.
		// Let's just split on the last @.
	}

	local := email[:atIndex]
	domain := email[atIndex+1:]

	// Validate local part
	if len(local) == 0 {
		return false, "empty local part"
	}
	if len(local) > 64 {
		return false, "local part exceeds 64 characters"
	}

	// Handle quoted local part
	if strings.HasPrefix(local, "\"") && strings.HasSuffix(local, "\"") {
		// Quoted string — almost anything goes inside quotes
		// Just check it's not empty quotes
		if len(local) == 2 {
			return false, "empty quoted local part"
		}
	} else {
		// Unquoted local part rules
		if strings.HasPrefix(local, ".") || strings.HasSuffix(local, ".") {
			return false, "local part cannot start or end with a dot"
		}
		if strings.Contains(local, "..") {
			return false, "local part cannot have consecutive dots"
		}
		// Allowed: alphanumeric + .!#$%&'*+/=?^_`{|}~-
		localRegex := regexp.MustCompile(`^[a-zA-Z0-9.!#$%&'*+/=?^_` + "`" + `{|}~-]+$`)
		if !localRegex.MatchString(local) {
			return false, "local part contains invalid characters"
		}
	}

	// Validate domain part
	if len(domain) == 0 {
		return false, "empty domain"
	}
	if len(domain) > 253 {
		return false, "domain exceeds 253 characters"
	}

	// IP address literal: [192.168.1.1] or [IPv6:...]
	if strings.HasPrefix(domain, "[") && strings.HasSuffix(domain, "]") {
		inner := domain[1 : len(domain)-1]
		if strings.HasPrefix(inner, "IPv6:") {
			inner = inner[5:]
		}
		if net.ParseIP(inner) == nil {
			return false, "invalid IP address in domain literal"
		}
		return true, ""
	}

	// Domain name validation
	if strings.HasPrefix(domain, ".") || strings.HasSuffix(domain, ".") {
		return false, "domain cannot start or end with a dot"
	}
	if strings.HasPrefix(domain, "-") || strings.HasSuffix(domain, "-") {
		return false, "domain cannot start or end with a hyphen"
	}
	if strings.Contains(domain, "..") {
		return false, "domain cannot have consecutive dots"
	}

	// Must have at least one dot (TLD required for real-world use)
	if !strings.Contains(domain, ".") {
		return false, "domain must have at least one dot"
	}

	// Each label: 1-63 chars, alphanumeric + hyphen, no leading/trailing hyphen
	labels := strings.Split(domain, ".")
	labelRegex := regexp.MustCompile(`^[a-zA-Z0-9]([a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?$`)
	for _, label := range labels {
		if len(label) == 0 {
			return false, "domain has empty label"
		}
		if len(label) > 63 {
			return false, "domain label exceeds 63 characters"
		}
		if !labelRegex.MatchString(label) {
			return false, "domain label contains invalid characters"
		}
	}

	// TLD must not be all-numeric
	tld := labels[len(labels)-1]
	allDigits := regexp.MustCompile(`^[0-9]+$`)
	if allDigits.MatchString(tld) {
		return false, "TLD cannot be all numeric"
	}

	return true, ""
}
```

Edge cases handled:

- Empty input, overall length (254 max per RFC 5321)
- Local part: max 64 chars, no leading/trailing/consecutive dots, restricted character set
- Quoted local parts (allows special chars inside quotes)
- Domain: max 253 chars, labels max 63 chars each, no leading/trailing hyphens
- IP address literals (`[192.168.1.1]`, `[IPv6:...]`)
- All-numeric TLD rejection (not a valid hostname)
- Multiple `@` — splits on the last one (valid per spec)

What this deliberately does NOT do:
- DNS/MX lookup (that's a network call, separate concern)
- Mailbox verification (SMTP VRFY — unreliable anyway)
- Full RFC 5322 comment/folding whitespace parsing (nobody uses that in practice)

If you want DNS validation on top, wrap this with a `net.LookupMX(domain)` call separately.

Here's a practical test suite for a nested JSON parser. I'll assume we're testing a `parseNestedJson` function that takes a string and returns a parsed object, with proper error handling.

```typescript
import { describe, it, expect } from 'vitest';
import { parseNestedJson } from './parseNestedJson';

describe('parseNestedJson', () => {
  // --- Basic cases ---

  it('parses a flat object', () => {
    const input = '{"name": "Alice", "age": 30}';
    expect(parseNestedJson(input)).toEqual({ name: 'Alice', age: 30 });
  });

  it('parses an empty object', () => {
    expect(parseNestedJson('{}')).toEqual({});
  });

  it('parses an empty array', () => {
    expect(parseNestedJson('[]')).toEqual([]);
  });

  // --- Nested structures ---

  it('parses a deeply nested object', () => {
    const input = '{"a": {"b": {"c": {"d": "value"}}}}';
    const result = parseNestedJson(input);
    expect(result.a.b.c.d).toBe('value');
  });

  it('parses nested arrays', () => {
    const input = '[[1, [2, [3, [4]]]]]';
    expect(parseNestedJson(input)).toEqual([[1, [2, [3, [4]]]]]);
  });

  it('parses mixed nested arrays and objects', () => {
    const input = '{"users": [{"name": "Bob", "tags": ["admin", "active"]}]}';
    const result = parseNestedJson(input);
    expect(result.users[0].name).toBe('Bob');
    expect(result.users[0].tags).toEqual(['admin', 'active']);
  });

  // --- Data types ---

  it('handles all JSON primitive types', () => {
    const input = '{"str": "hello", "num": 42, "float": 3.14, "bool": true, "nil": null}';
    const result = parseNestedJson(input);
    expect(result.str).toBe('hello');
    expect(result.num).toBe(42);
    expect(result.float).toBeCloseTo(3.14);
    expect(result.bool).toBe(true);
    expect(result.nil).toBeNull();
  });

  it('handles negative numbers and exponents', () => {
    const input = '{"neg": -1, "exp": 1.5e10}';
    const result = parseNestedJson(input);
    expect(result.neg).toBe(-1);
    expect(result.exp).toBe(1.5e10);
  });

  // --- Edge cases ---

  it('handles escaped characters in strings', () => {
    const input = '{"msg": "line1\\nline2\\ttab \\"quoted\\""}';
    const result = parseNestedJson(input);
    expect(result.msg).toBe('line1\nline2\ttab "quoted"');
  });

  it('handles unicode escape sequences', () => {
    const input = '{"emoji": "\\u0048\\u0065\\u006C\\u006C\\u006F"}';
    const result = parseNestedJson(input);
    expect(result.emoji).toBe('Hello');
  });

  it('handles large nested structures without stack overflow', () => {
    // 100 levels deep
    let input = '{"a":'.repeat(100) + '1' + '}'.repeat(100);
    expect(() => parseNestedJson(input)).not.toThrow();
  });

  it('handles empty strings as values', () => {
    expect(parseNestedJson('{"key": ""}')).toEqual({ key: '' });
  });

  it('handles duplicate keys (last one wins per spec)', () => {
    const input = '{"a": 1, "a": 2}';
    const result = parseNestedJson(input);
    expect(result.a).toBe(2);
  });

  // --- Error handling ---

  it('throws on invalid JSON', () => {
    expect(() => parseNestedJson('{invalid}')).toThrow();
  });

  it('throws on trailing commas', () => {
    expect(() => parseNestedJson('{"a": 1,}')).toThrow();
  });

  it('throws on single quotes', () => {
    expect(() => parseNestedJson("{'a': 1}")).toThrow();
  });

  it('throws on empty input', () => {
    expect(() => parseNestedJson('')).toThrow();
  });

  it('throws on undefined/null input', () => {
    expect(() => parseNestedJson(undefined as any)).toThrow();
    expect(() => parseNestedJson(null as any)).toThrow();
  });

  it('throws on excessively deep nesting (DoS protection)', () => {
    const input = '['.repeat(10000) + ']'.repeat(10000);
    expect(() => parseNestedJson(input)).toThrow(/depth|recursion/i);
  });

  // --- Whitespace handling ---

  it('handles various whitespace formatting', () => {
    const input = `{
      "key" :   "value" ,
      "nested" : {
        "arr" : [ 1 , 2 , 3 ]
      }
    }`;
    expect(parseNestedJson(input)).toEqual({ key: 'value', nested: { arr: [1, 2, 3] } });
  });
});
```

Key decisions in this test suite:

- Tests are grouped by concern: basic, nested, types, edge cases, errors, whitespace.
- The DoS protection test assumes your parser has a max depth guard. If it's just a `JSON.parse` wrapper, remove that or adjust the expectation.
- Duplicate keys test documents the "last wins" behavior — this is implementation-defined but matches most parsers.
- The deep nesting test (100 levels) checks that normal recursion works, while the 10,000-level test checks that pathological input is rejected.

Adapt the import path and error messages to match your actual implementation. If your parser has additional features (streaming, reviver functions, custom types), add corresponding test groups.
